DROP TABLE IF EXISTS `expense_test_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expense_test_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `test_order_no` varchar(100) NOT NULL COMMENT '试验单号',
  `total_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '总金额',
  `used_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '已使用金额(实时)',
  `planned_start_time` date DEFAULT NULL COMMENT '计划开展时间',
  `planned_end_time` date DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` date DEFAULT NULL COMMENT '实际开展时间',
  `actual_end_time` date DEFAULT NULL COMMENT '实际结束时间',
  `supplier` varchar(50) DEFAULT NULL COMMENT '供应商',
  `outsourced_count` int NOT NULL DEFAULT '0' COMMENT '委外人数',
  `responsible_person` varchar(50) DEFAULT NULL COMMENT '负责人',
  `is_used` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已使用',
  `remark` longtext COMMENT '备注',
  `expense_code_id` bigint DEFAULT NULL COMMENT '所属费用号',
  `settlement_amount` decimal(12,2) DEFAULT NULL COMMENT '结算数据(手动输入)',
  `last_month_used` decimal(12,2) DEFAULT NULL COMMENT '截止到上月已使用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `test_order_no` (`test_order_no`),
  KEY `fk_expense__expense__c7b6a75e` (`expense_code_id`),
  KEY `idx_expense_tes_created_983312` (`created_at`),
  KEY `idx_expense_tes_updated_ec050a` (`updated_at`),
  KEY `idx_expense_tes_test_or_1def79` (`test_order_no`),
  CONSTRAINT `fk_expense__expense__c7b6a75e` FOREIGN KEY (`expense_code_id`) REFERENCES `expense_code` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=154 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='试验单号';
